// Create a game test
@GameTestHolder
public class MyBlockTests {
    private static final int TICK_WAIT = 20;

    @Test("mymod:my_block_test")
    public void testMyBlock(GameTestHelper helper) {
        // Place a block
        helper.setBlock(new BlockPos(0, 1, 0), MyBlocks.MY_BLOCK.get());

        // Wait for block to update
        helper.sleep(TICK_WAIT);

        // Verify block state
        BlockState state = helper.getBlockState(new BlockPos(0, 1, 0));
        helper.assertTrue(
            state.is(MyBlocks.MY_BLOCK.get()), 
            "Block should be my block"
        );

        // Success
        helper.succeed();
    }

    @Test("mymod:redstone_test")
    public void testRedstonePower(GameTestHelper helper) {
        // Create test for block powering
        helper.setBlock(new BlockPos(0, 1, 0), Blocks.REDSTONE_BLOCK);
        helper.sleep(TICK_WAIT);

        // Test passes if no errors
        helper.succeed();
    }
}
